package org.apache.commons.lang.time;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Calendar;
import java.util.Date;
import java.util.TimeZone;
import org.apache.commons.lang.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for DurationFormatUtils.formatDuration
 */
public class DurationFormatUtils_formatDuration_TriageGen2Test {

    @Test
    public void testFormatDuration_AllTokens_WithPadding() {
        // 1 day, 2 hours, 3 minutes, 4 seconds, 567 milliseconds
        long duration = (24 * 60 * 60 * 1000L) + (2 * 60 * 60 * 1000L) + (3 * 60 * 1000L) + (4 * 1000L) + 567L;
        String format = "d' days 'H' hours 'm' minutes 's' seconds 'S' ms";
        String result = DurationFormatUtils.formatDuration(duration, format, true);
        assertEquals("1 days 02 hours 03 minutes 04 seconds 567 ms", result);
    }

    @Test
    public void testFormatDuration_AllTokens_NoPadding() {
        long duration = (24 * 60 * 60 * 1000L) + (2 * 60 * 60 * 1000L) + (3 * 60 * 1000L) + (4 * 1000L) + 567L;
        String format = "d' days 'H' hours 'm' minutes 's' seconds 'S' ms";
        // Note: padWithZeros affects the numeric parts handled by the format method
        String result = DurationFormatUtils.formatDuration(duration, format, false);
        assertEquals("1 days 2 hours 3 minutes 4 seconds 567 ms", result);
    }

    @Test
    public void testFormatDuration_OnlyHoursAndMinutes() {
        long duration = (2 * 60 * 60 * 1000L) + (3 * 60 * 1000L);
        String format = "H'h 'm'm'";
        String result = DurationFormatUtils.formatDuration(duration, format, true);
        assertEquals("02h 03m", result);
    }

    @Test
    public void testFormatDuration_OnlySeconds() {
        long duration = 45000L; // 45 seconds
        String format = "s's'";
        String result = DurationFormatUtils.formatDuration(duration, format, false);
        assertEquals("45s", result);
    }

    @Test
    public void testFormatDuration_OnlyMilliseconds() {
        long duration = 123L;
        String format = "S'ms'";
        String result = DurationFormatUtils.formatDuration(duration, format, false);
        assertEquals("123ms", result);
    }

    @Test
    public void testFormatDuration_ZeroDuration() {
        long duration = 0L;
        String format = "d'd 'H'h 'm'm 's's 'S'S";
        String result = DurationFormatUtils.formatDuration(duration, format, true);
        assertEquals("0d 00h 00m 00s 000S", result);
    }

    @Test
    public void testFormatDuration_LargeDuration_DaysOnly() {
        long duration = 5L * 24 * 60 * 60 * 1000L;
        String format = "d' days'";
        String result = DurationFormatUtils.formatDuration(duration, format, false);
        assertEquals("5 days", result);
    }

    @Test
    public void testFormatDuration_PartialTokens() {
        // Test that if a token is missing from the format string, it is not calculated/included
        // duration: 1h 30m
        long duration = (1 * 60 * 60 * 1000L) + (30 * 60 * 1000L);
        String format = "m'm'"; 
        // Even though duration has hours, the format only asks for minutes
        String result = DurationFormatUtils.formatDuration(duration, format, true);
        assertEquals("30m", result);
    }

    @Test
    public void testFormatDuration_MixedTokens() {
        long duration = (10 * 60 * 1000L) + 500L; // 10m 500ms
        String format = "m'm 'S'ms'";
        String result = DurationFormatUtils.formatDuration(duration, format, true);
        assertEquals("10m 500ms", result);
    }

    @Test
    public void testFormatDuration_NoTokensInFormat() {
        long duration = 1000L;
        String format = "Just text";
        String result = DurationFormatUtils.formatDuration(duration, format, false);
        assertEquals("Just text", result);
    }
}
